import pathlib,json,sys,numpy as np
r=pathlib.Path(__file__).parent;out=r/sys.argv[1];out.mkdir(exist_ok=True);a0=9.3603e-11;kpc=3.085677581491367e19;rows=[]
for name in ['NGC2403','NGC3198','DDO154']:
 d=np.loadtxt(r/f'inputs/{name}_rotmod.dat');d=d[(d[:,0]>0)&(d[:,1]>0)&(d[:,2]>0)];R,V,eV,Vg,Vd=d[:,:5].T
 star=.5*Vd**2*1e6/(R*kpc);gas=np.sign(Vg)*Vg**2*1e6/(R*kpc);S=star+gas;Y=S/a0;f=gas/S;g=(S+np.sqrt(S*S+4*S*a0))/2;t=a0/(g+2*a0);a=(1-t)*(1-f);err=2*eV/V
 # Quotient q=lnT-lnAgas; nuisance span is{globalvelocityamplitude,stellar/gascontrast}.
 N=np.column_stack([np.ones(len(R)),a]);coef=np.linalg.lstsq(N/err[:,None],t/err,rcond=None)[0];res=t-N@coef;I=float(np.sum((res/err)**2));trans=(Y>.3)&(Y<3);gasdom=f>.5;overlap=gasdom&trans
 rows.append(dict(name=name,valid_rows=len(R),gas_dominated_rows=int(gasdom.sum()),transition_rows=int(trans.sum()),gas_dominated_transition_rows=int(overlap.sum()),gas_dominated_above_y0_3_rows=int((gasdom&(Y>.3)).sum()),gbar_over_a0_range=[float(Y.min()),float(Y.max())],gas_fraction_range=[float(f.min()),float(f.max())],max_gas_fraction_among_transition=None if not trans.any() else float(f[trans].max()),max_y_among_gas_dominated=None if not gasdom.any() else float(Y[gasdom].max()),quotient_logw_response_range=[float(t.min()),float(t.max())],quotient_fisher_information_after_amplitude_and_star_gas_projection=I,optimistic_sigma_log10_quotient_if_shape_exact=float(1/(np.log(10)*np.sqrt(I))),weighted_response_residual_rms=float(np.sqrt(np.mean((res/err)**2))),gas_dominated_transition_radii_kpc=R[overlap].tolist()))
res=dict(assertion_tested='Illustrative gasfraction/transitioncounts and exact local nuisance-projectioninformation on three oldtemplate radialgrids;not fittedlawresiduals.',thresholds={'gas_fraction_greater_than':.5,'transition_y_strict': [.3,3]},rows=rows,formula='t=a0/(g+2a0);nuisancespan{1,(1-t)fstar};I_q=||W^(1/2)(t-P_N t)||^2.',nonclaims=['Thresholdsareillustrative,notcompleteoroptimizedselectionrule','Galaxy templatesincludeSPARCgeometryandcanonicalUpsilon.5','No gas/starmapcovariance,externalfield,PSForradialM/Luncertainty','PositiveHI/molecularcalibrationclaimsnotmade'])
(out/'results.json').write_text(json.dumps(res,indent=2))
for x in rows:print(x['name'],'N',x['valid_rows'],'gas',x['gas_dominated_rows'],'transition',x['transition_rows'],'overlap',x['gas_dominated_transition_rows'],'optimistic_sigma_log10S',x['optimistic_sigma_log10_quotient_if_shape_exact'])
